    // 核心命中与弹着计算函数
    function calculateHits() {
      const resultTextarea = document.getElementById('result_text');

      try {
        const shellCountStr = document.getElementById('shell_count').value.trim();
        const baseFireControlStr = document.getElementById('base_fire_control').value.trim();

        if (shellCountStr === '' || baseFireControlStr === '') {
          throw new Error('Required fields empty');
        }

        const shell_count = parseInt(shellCountStr, 10);
        const base_fire_control = parseInt(baseFireControlStr, 10);

        if (isNaN(shell_count) || isNaN(base_fire_control) || shell_count <= 0) {
          throw new Error('Invalid values');
        }

        let modifiers = 0;
        const modifier_details = [];

        // 1. 能见度修正
        const visibility = document.getElementById('visibility').value;
        if (visibility.includes('+1')) {
          modifiers += 1;
          modifier_details.push('能见度 (8-9): +1');
        } else if (visibility.includes('-2')) {
          modifiers += -2;
          modifier_details.push('能见度 (4-5): -2');
        } else if (visibility.includes('-4')) {
          modifiers += -4;
          modifier_details.push('能见度 (1-3): -4');
        }

        // 2. 时间修正
        const time_of_day = timeOfDaySelect.value;
        if (time_of_day === '晨昏') {
          const sunPosElem = document.getElementById('sun_position');
          const sun_pos = sunPosElem ? sunPosElem.value : '无影响 (0)';
          if (sun_pos.includes('+1')) {
            modifiers += 1;
            modifier_details.push('太阳位置 (目标在太阳方向): +1');
          } else if (sun_pos.includes('-2')) {
            modifiers += -2;
            modifier_details.push('太阳位置 (本舰在太阳方向): -2');
          }
        } else if (time_of_day === '夜间') {
          const moonElem = document.getElementById('moonlight');
          const moonlight = moonElem ? moonElem.value : '无月光 (-4)';
          if (moonlight.includes('-2')) {
            modifiers += -2;
            modifier_details.push('月光 (有月光): -2');
          } else if (moonlight.includes('-4')) {
            modifiers += -4;
            modifier_details.push('月光 (无月光): -4');
          }
        }

        // 3. 目标状态修正
        if (document.getElementById('on_fire').checked) {
          modifiers += 2;
          modifier_details.push('目标状态 (着火/被探照灯照射): +2');
        }

        if (document.getElementById('using_searchlight').checked) {
          modifiers += 1;
          modifier_details.push('目标状态 (使用探照灯/被照明弹照亮): +1');
        }

        if (document.getElementById('blind_fire').checked) {
          modifiers += -5;
          modifier_details.push('目标状态 (盲射): -5');
        }

        // 4. 烟雾修正
        const battleSmokeStr = document.getElementById('battle_smoke').value.trim();
        const battle_smoke = battleSmokeStr === '' ? 0 : parseInt(battleSmokeStr, 10);
        if (isNaN(battle_smoke)) throw new Error('Invalid battle_smoke');
        if (battle_smoke > 0) {
          modifiers -= battle_smoke;
          modifier_details.push(`战斗烟雾: -${battle_smoke}`);
        }

        const boilerSmokeStr = document.getElementById('boiler_smoke').value.trim();
        const boiler_smoke = boilerSmokeStr === '' ? 0 : parseInt(boilerSmokeStr, 10);
        if (isNaN(boiler_smoke)) throw new Error('Invalid boiler_smoke');
        if (boiler_smoke > 0) {
          modifiers -= boiler_smoke * 3;
          modifier_details.push(`锅炉烟雾: -${boiler_smoke * 3}`);
        }

        // 5. 机动规避修正
        const evasion = document.getElementById('evasion').value;
        if (evasion.includes('-3')) {
          modifiers += -3;
          modifier_details.push('机动规避 (仅目标机动): -3');
        } else if (evasion.includes('-2')) {
          modifiers += -2;
          modifier_details.push('机动规避 (仅本舰机动): -2');
        } else if (evasion.includes('-8')) {
          modifiers += -8;
          modifier_details.push('机动规避 (双方机动): -8');
        }

        // 6. 射击历史修正
        const fire_history = document.getElementById('fire_history').value;
        if (fire_history.includes('-2')) {
          modifiers += -2;
          modifier_details.push('射击历史 (首次射击): -2');
        } else if (fire_history.includes('+2')) {
          modifiers += 2;
          modifier_details.push('射击历史 (上轮击中): +2');
        }

        // 7. 多船射击修正
        if (document.getElementById('multi_ship_fire').checked) {
          modifiers += -2;
          modifier_details.push('3条船及以上对本舰射击: -2');
        }

        // 8. 炮组数量修正
        const normalGroupsStr = document.getElementById('normal_fire_groups').value.trim();
        const normal_groups = normalGroupsStr === '' ? 1 : parseInt(normalGroupsStr, 10);
        if (isNaN(normal_groups)) throw new Error('Invalid normal_groups');
        if (normal_groups > 1) {
          const mod = normal_groups - 1;
          modifiers -= mod;
          modifier_details.push(`正常向射击炮组数量: -${mod}`);
        }

        const concentratedGroupsStr = document.getElementById('concentrated_fire_groups').value.trim();
        const concentrated_groups = concentratedGroupsStr === '' ? 0 : parseInt(concentratedGroupsStr, 10);
        if (isNaN(concentrated_groups)) throw new Error('Invalid concentrated_groups');
        if (concentrated_groups > 0) {
          const mod = concentrated_groups * 2;
          modifiers += mod;
          modifier_details.push(`密集向射击炮组数量: +${mod}`);
        }

        // 9. 目标尺寸修正
        const target_size = parseInt(document.getElementById('target_size').value, 10);
        if (target_size !== 0) {
          modifiers += target_size;
          modifier_details.push(`目标尺寸修正: +${target_size}`);
        }

        // 10. 炮兵观察飞机修正
        if (document.getElementById('spotter_plane').checked) {
          modifiers += 2;
          modifier_details.push('炮兵观察飞机: +2');
        }

        // 11. 战斗修正（BR）
        const brStr = document.getElementById('battle_rating').value.trim();
        const battle_rating = brStr === '' ? 0 : parseInt(brStr, 10);
        if (isNaN(battle_rating)) throw new Error('Invalid battle_rating');
        if (battle_rating !== 0) {
          modifiers += battle_rating;
          modifier_details.push(`战斗修正（BR）: ${battle_rating > 0 ? '+' : ''}${battle_rating}`);
        }

        // 12. 雷达修正
        const radarStr = document.getElementById('radar').value.trim();
        const radar = radarStr === '' ? 0 : parseInt(radarStr, 10);
        if (isNaN(radar)) throw new Error('Invalid radar');
        if (radar !== 0) {
          modifiers += radar;
          modifier_details.push(`雷达修正: ${radar > 0 ? '+' : ''}${radar}`);
        }

        // 13. 其他修正
        const otherStr = document.getElementById('other_modifiers').value.trim();
        const other_modifiers = otherStr === '' ? 0 : parseInt(otherStr, 10);
        if (isNaN(other_modifiers)) throw new Error('Invalid other_modifiers');
        if (other_modifiers !== 0) {
          modifiers += other_modifiers;
          modifier_details.push(`其他修正: ${other_modifiers > 0 ? '+' : ''}${other_modifiers}`);
        }

        // 计算最终火控值
        let final_fire_control = base_fire_control + modifiers;

        // 限制火控值范围
        if (final_fire_control < 0) {
          const result = "命中概率: 0%\n命中数: 0\n最终火控值: " + final_fire_control + "\n修正值: " + modifiers + "\n修正详情:\n" + (modifier_details.length ? modifier_details.join('\n') : '无');
          resultTextarea.value = result;
          lastLocationStats = {};
          lastHitsState = { shellCount: shell_count, hits: 0, calculated: true };
          lastDamageState = { totalDamage: 0, effects: [], calculated: false };
          return;
        } else if (final_fire_control > 30) {
          final_fire_control = 30;
        }

        // 查找千分比命中概率
        const hit_probability = HIT_TABLE[final_fire_control] || 0;

        // 判定各炮弹
        const random_numbers = [];
        for (let i = 0; i < shell_count; i++) {
          random_numbers.push(Math.floor(Math.random() * 1000) + 1);
        }

        let hits = 0;
        let random_results = "\n随机数判定结果:";
        let hit_locations = "\n命中位置判定结果:";
        const location_stats = {};

        const distance = document.getElementById('target_distance').value;
        const ship_type = document.getElementById('ship_type').value;
        const target_profile = document.getElementById('target_profile').value;

        for (let i = 0; i < random_numbers.length; i++) {
          const num = random_numbers[i];
          const shellIndex = i + 1;
          const hit_status = num <= hit_probability ? "命中" : "未命中";
          random_results += `\n炮弹${shellIndex}: ${num} (D1000 ${hit_status})`;

          if (num <= hit_probability) {
            hits++;
            const location_dice = Math.floor(Math.random() * 100) + 1;

            let hit_table_selected;
            if (ship_type === "航母") {
              hit_table_selected = HIT_LOCATION_CV;
            } else {
              hit_table_selected = target_profile === "宽" ? HIT_LOCATION_BRD : HIT_LOCATION_NRW;
            }

            const entries = hit_table_selected[distance] || [];
            for (let k = 0; k < entries.length; k++) {
              const entry = entries[k];
              if (location_dice >= entry.min && location_dice <= entry.max) {
                const loc = entry.location;
                hit_locations += `\n炮弹${shellIndex}: D100=${location_dice} -> ${loc}`;
                location_stats[loc] = (location_stats[loc] || 0) + 1;
                break;
              }
            }
          }
        }

        // 命中部位统计
        let stats_result = "\n\n命中部位统计:";
        const sortedLocations = Object.keys(location_stats).sort();
        if (sortedLocations.length === 0) {
          stats_result += "\n无命中";
        } else {
          for (let k = 0; k < sortedLocations.length; k++) {
            const loc = sortedLocations[k];
            stats_result += `\n${loc}: ${location_stats[loc]}次`;
          }
        }

        const details = modifier_details.length ? modifier_details.join('\n') : '无';
        const fullResult = `最终火控值: ${final_fire_control}\n命中概率: ${hit_probability}‰\n命中数: ${hits}${stats_result}\n\n修正值: ${modifiers}\n修正详情:\n${details}${random_results}${hit_locations}`;

        resultTextarea.value = fullResult;
        lastLocationStats = location_stats;
        lastHitsState = { shellCount: shell_count, hits: hits, calculated: true };
        lastDamageState = { totalDamage: 0, effects: [], calculated: false };

      } catch (err) {
        resultTextarea.value = "请输入有效的数值";
        lastLocationStats = {};
        lastHitsState = { shellCount: 0, hits: 0, calculated: false };
        lastDamageState = { totalDamage: 0, effects: [], calculated: false };
      }
    }

    // 损伤计算
    function calculateDamage() {
      const damageResultTextarea = document.getElementById('damage_result_text');

      try {
        const bore = document.getElementById('bore').value;
        const shipPenStr = document.getElementById('ship_penetration').value;
        const shell_type = document.getElementById('shell_type').value;
        const dfVal = parseInt(document.getElementById('damage_factor').value, 10);
        const launchDate = document.getElementById('launch_date').value;
        const LAUNCH_LABEL = { "1905": "1880-1905", "1922": "1906-1922", "1945": "1923-1945", "CV": "航母及类似母舰(1915-1945)" };

        const ship_penetration = parseFloat(shipPenStr);
        if (isNaN(ship_penetration) || ship_penetration < 0) {
          throw new Error('Invalid ship penetration');
        }
        if (!DAMAGE_TABLE[dfVal]) {
          throw new Error('Invalid damage factor');
        }

        // 计算实际穿甲值
        let actual_penetration = 0;
        if (shell_type === "AP") {
          actual_penetration = ship_penetration;
        } else if (shell_type === "SAP") {
          actual_penetration = Math.round(ship_penetration * 0.75 * 10000) / 10000;
        } else if (shell_type === "COM" || shell_type === "HE") {
          const tableVal = (HE_PEN_TABLE[bore] && HE_PEN_TABLE[bore][shipPenStr] !== undefined) 
            ? HE_PEN_TABLE[bore][shipPenStr] 
            : null;
          if (tableVal === null) {
            damageResultTextarea.value = "所选口径在当前船表穿甲值下无对应HE/COM穿深数据（现实中不可能存在），请核对选项";
            return;
          }
          actual_penetration = tableVal;
        }

        // 获取各部位装甲值
        const armorKeys = ['1H', '2H', '3H', '4V', '5V', '6V', '7V', '8V', '9V'];
        const armor = {};
        for (let i = 0; i < armorKeys.length; i++) {
          const key = armorKeys[i];
          const valStr = document.getElementById(`armor_${key}`).value.trim();
          const val = valStr === '' ? 0 : parseFloat(valStr);
          if (isNaN(val) || val < 0) {
            throw new Error(`Invalid armor ${key}`);
          }
          armor[key] = val;
        }

        // 掷 D100（1-100）
        const d100 = () => Math.floor(Math.random() * 100) + 1;

        // DE 详细说明查询：DE 出现后输出中文描述 + 执行附加表掷骰 + 追加（递归一次）
        function resolveDeDetail(grade, shell, deNum) {
          const det = DE_TEXT[deNum];
          if (!det) return { lines: ["    [DE" + deNum + "：暂无详细说明]"] };
          const lines = [];
          let mainText = "";
          if (grade === "A" || grade === "B") mainText = det.AB || det["A"] || det["B"] || "";
          else if (grade === "C") mainText = det.C || "";
          lines.push("    [DE" + deNum + " 穿甲等级" + grade + "（" + shell + "）] " + mainText);
          if (shell === "HE") {
            if (det.HE && det.HE.type === "asClass") {
              lines.push("    [HE 适用] HE 弹药按对应穿甲等级 (" + grade + ") 受效果：同 A/B 描述。");
            } else if (det.HE && det.HE.type === "specific" && det.HE.text) {
              lines.push("    [HE 适用] " + det.HE.text);
            }
          }
          if (det.internal) {
            for (let i = 0; i < det.internal.length; i++) {
              const it = det.internal[i];
              let active = true;
              if (it.scope) {
                if (it.scope === "A") active = grade === "A";
                else if (it.scope === "B") active = grade === "B";
                else if (it.scope === "C") active = grade === "C";
                else if (it.scope === "AB") active = true;
                else if (it.scope === "HE") active = shell === "HE";
                else if (it.scope === "HE_A") active = shell === "HE" && grade === "A";
                else if (it.scope === "HE_B") active = shell === "HE" && grade === "B";
                else if (it.scope === "HE_C") active = shell === "HE" && grade === "C";
              }
              if (!active) continue;
              const r = d100();
              const hit = r <= parseInt(it.need.split('-')[1], 10) && r >= parseInt(it.need.split('-')[0], 10);
              lines.push("    [内嵌判定] D100=" + r + "（需 " + it.need + "）→ " + (hit ? "✓ " : "✗ ") + it.then);
            }
          }
          let added = null;
          if (det.add && (grade === "A" || grade === "B")) {
            const tb = (grade === "A" && det.add.A) ? det.add.A : ((grade === "B" && det.add.B) ? det.add.B : (det.add.AB || det.add));
            const r = d100();
            let val = null;
            for (let b = 0; b < tb.length; b++) {
              if (r >= tb[b][0] && r <= tb[b][1]) { val = tb[b][2]; break; }
            }
            lines.push("    [附加表] D100=" + r + " → 追加DE: " + (val && val > 0 ? val : "无"));
            if (val && val > 0) added = val;
          }
          return { lines, add: added };
        }

                // DE 编号查询：DE 出现后再掷 D100，按下水时间选表、按部位选列
        function queryDeNum(locCol) {
          const table = DE_TABLE[launchDate];
          if (!table) return null;
          const deRoll = d100();
          for (let i = 0; i < table.length; i++) {
            const band = table[i];
            if (deRoll >= band.l && deRoll <= band.h) {
              return band.v[locCol] !== undefined ? band.v[locCol] : null;
            }
          }
          return null;
        }

        // 按等级判定具体损伤值与 DE
        // 返回 { dmg, de, deNum }
        function resolveHitDamage(grade, shell, locCol) {
          const row = DAMAGE_TABLE[dfVal];
          if (grade === "A") {
            // 按弹种查 D100 分档表，掷骰得伤害
            const bands = row[shell.toLowerCase()];
            const rollDmg = d100();
            let dmg = 0;
            for (let b = 0; b < bands.length; b++) {
              if (rollDmg >= bands[b][0] && rollDmg <= bands[b][1]) {
                dmg = bands[b][2];
                break;
              }
            }
            if (d100() <= row.de) {
              return { dmg, de: true, deNum: queryDeNum(locCol) };
            }
            return { dmg, de: false, deNum: null };
          } else if (grade === "B") {
            const dmg = row.b;
            if (d100() <= row.bde) {
              return { dmg, de: true, deNum: queryDeNum(locCol) };
            }
            return { dmg, de: false, deNum: null };
          } else {
            // C 级：按弹种取固定伤害；DE 看 T 列，无则不用判定
            let dmg = 0;
            if (shell === "AP") dmg = row.cap;
            else if (shell === "SAP") dmg = row.csap;
            else if (shell === "COM") dmg = row.ccom;
            else if (shell === "HE") dmg = row.che;
            if (row.cde !== null && d100() <= row.cde) {
              return { dmg, de: true, deNum: queryDeNum(locCol) };
            }
            return { dmg, de: false, deNum: null };
          }
        }

        let totalDmgAccum = 0;
        const damageEffectsList = [];

        let damage_result = "损伤判定结果：\n";
        damage_result += `火炮口径：${bore}\n`;
        damage_result += `炮弹类型：${shell_type}\n`;
        damage_result += `船表火炮穿甲值：${shipPenStr}\n`;
        damage_result += `实际穿甲值：${actual_penetration}\n`;
        damage_result += `火炮伤害值：${dfVal}\n`;
        damage_result += `目标下水时间：${LAUNCH_LABEL[launchDate] || launchDate}\n\n`;

        const sortedLocations = Object.keys(lastLocationStats).sort();
        const validLocations = sortedLocations.filter(loc => !loc.includes("跨射") && !loc.includes("未命中"));

        if (validLocations.length === 0) {
          damage_result += "无命中目标部位需判定。";
          damageResultTextarea.value = damage_result;
          lastDamageState = { totalDamage: 0, effects: [], calculated: true };
          return;
        }

        for (let i = 0; i < sortedLocations.length; i++) {
          const loc_name = sortedLocations[i];
          if (loc_name.includes("跨射") || loc_name.includes("未命中")) {
            continue;
          }

          const hit_count = lastLocationStats[loc_name];
          const match = loc_name.match(/^[1-9][HV]/);
          const base_loc = match ? match[0] : loc_name.split('（')[0];
          const armor_value = armor[base_loc] !== undefined ? armor[base_loc] : 0;

          damage_result += `${loc_name} (${hit_count}次命中):\n`;

          for (let h = 0; h < hit_count; h++) {
            const roll = d100();
            let grade = "";   // A / B / C
            let gradeText = "";

            if (armor_value > 0) {
              if (actual_penetration >= armor_value && actual_penetration <= 2 * armor_value) {
                grade = "A";
                gradeText = "穿甲，等级A";
              } else if (actual_penetration > 2 * armor_value) {
                if ((shell_type === "AP" && roll <= 30) ||
                    (shell_type === "SAP" && roll <= 50) ||
                    (shell_type === "COM" && roll <= 70) ||
                    (shell_type === "HE" && roll <= 90)) {
                  grade = "A";
                  gradeText = "穿甲，等级A";
                } else {
                  grade = "B";
                  gradeText = "过穿，等级B";
                }
              } else {
                grade = "C";
                gradeText = "未击穿，等级C";
              }
            } else {
              if ((shell_type === "AP" && roll <= 20) ||
                  (shell_type === "SAP" && roll <= 40) ||
                  (shell_type === "COM" && roll <= 70) ||
                  (shell_type === "HE" && roll <= 90)) {
                grade = "A";
                gradeText = "穿甲，等级A";
              } else {
                grade = "B";
                gradeText = "过穿，等级B";
              }
            }

            const locCol = parseInt(base_loc.replace(/[HV]/, ''), 10);
            const hit = resolveHitDamage(grade, shell_type, locCol);
            totalDmgAccum += hit.dmg;

            if (hit.de && hit.deNum !== null) {
              damage_result += `  第${h + 1}发: ${gradeText}，损伤${hit.dmg}点，DE:${hit.deNum}\n`;
              const det = resolveDeDetail(grade, shell_type, hit.deNum);
              for (let li = 0; li < det.lines.length; li++) damage_result += det.lines[li] + "\n";

              // 收集总结所需的 DE 描述
              let deDesc = "";
              const deObj = DE_TEXT[hit.deNum];
              if (deObj) {
                if (grade === "A" || grade === "B") deDesc = deObj.AB || deObj["A"] || deObj["B"] || "";
                else if (grade === "C") deDesc = deObj.C || "";
              }
              // 提取内嵌判定结果
              let internalNotes = [];
              if (det.lines) {
                for (let li = 0; li < det.lines.length; li++) {
                  const line = det.lines[li];
                  if (line.includes("[内嵌判定]")) {
                    internalNotes.push(line.replace(/^\s*\[内嵌判定\]\s*/, ''));
                  }
                }
              }
              if (internalNotes.length > 0) {
                deDesc += "（" + internalNotes.join("；") + "）";
              }
              damageEffectsList.push({
                deNum: hit.deNum,
                desc: deDesc
              });

              if (det.add !== null) {
                const addDet = DE_TEXT[det.add];
                let addDesc = "";
                if (addDet) {
                  addDesc = (addDet.AB || addDet.C || "");
                  damage_result += "    [追加DE:" + det.add + " 穿甲等级" + grade + "（" + shell_type + "）] " + addDesc + "\n";
                } else {
                  damage_result += "    [追加DE:" + det.add + "：暂无详细说明]\n";
                }
                damageEffectsList.push({
                  deNum: det.add,
                  desc: addDesc ? `[追加DE] ${addDesc}` : "[追加DE]"
                });
              }
            } else if (hit.de) {
              damage_result += `  第${h + 1}发: ${gradeText}，损伤${hit.dmg}点，DE\n`;
            } else {
              damage_result += `  第${h + 1}发: ${gradeText}，损伤${hit.dmg}点\n`;
            }
          }

          damage_result += "\n";
        }

        damageResultTextarea.value = damage_result;
        lastDamageState = {
          totalDamage: totalDmgAccum,
          effects: damageEffectsList,
          calculated: true
        };

      } catch (err) {
        damageResultTextarea.value = "请输入有效的数值";
        lastDamageState = { totalDamage: 0, effects: [], calculated: false };
      }
    }

    // 复制功能
    const toast = document.getElementById('toast');
    const toastText = document.getElementById('toast_text');
    let toastTimer = null;

    function showToast(msg) {
      toastText.textContent = msg;
      toast.classList.add('show');
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toast.classList.remove('show');
      }, 2200);
    }

    async function copyToClipboard(text, successMsg) {
      if (!text || text.trim() === '') {
        showToast('暂无内容可复制');
        return;
      }
      try {
        if (navigator.clipboard && window.isSecureContext) {
          await navigator.clipboard.writeText(text);
          showToast(successMsg);
          return;
        }
      } catch (e) {
        // fallback below
      }

      const textArea = document.createElement('textarea');
      textArea.value = text;
      textArea.style.position = 'fixed';
      textArea.style.left = '-999999px';
      textArea.style.top = '-999999px';
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();
      try {
        const successful = document.execCommand('copy');
        if (successful) {
          showToast(successMsg);
        } else {
          showToast('复制失败，请手动选择复制');
        }
      } catch (err) {
        showToast('复制失败，请手动选择复制');
      }
      document.body.removeChild(textArea);
    }

    // 按钮事件绑定
    document.getElementById('fire_button').addEventListener('click', calculateHits);
    document.getElementById('calc_damage_btn').addEventListener('click', calculateDamage);

    document.getElementById('copy_report_btn').addEventListener('click', () => {
      const text = document.getElementById('result_text').value;
      copyToClipboard(text, '已复制到剪贴板');
    });

    
    // 生成最终总结
    function generateSummary() {
      const summaryTextarea = document.getElementById('summary_text');

      if (!lastHitsState.calculated) {
        showToast('请先输入发射参数并点击【发射】计算命中');
        summaryTextarea.value = '提示：尚未进行命中计算。请先设置参数并点击【发射】。';
        return;
      }

      const shellCount = lastHitsState.shellCount;
      const hits = lastHitsState.hits;

      // 如果未命中任何炮弹
      if (hits === 0) {
        const text = `本次炮击发射炮弹${shellCount}枚，命中0枚，共计造成0点伤害、0个损伤效果。`;
        summaryTextarea.value = text;
        showToast('已生成最终总结');
        return;
      }

      // 如果命中了炮弹，但尚未进行损伤判定
      if (!lastDamageState.calculated) {
        showToast('请先点击【计算损伤】完成判定');
        summaryTextarea.value = '提示：命中计算已完成（命中 ' + hits + ' 枚），请继续点击【计算损伤】完成损伤判定后再输出总结。';
        return;
      }

      const totalDmg = lastDamageState.totalDamage;
      const effects = lastDamageState.effects;
      const deCount = effects.length;

      const lines = [
        `本次炮击发射炮弹${shellCount}枚，命中${hits}枚，共计造成${totalDmg}点伤害、${deCount}个损伤效果。`
      ];

      if (deCount > 0) {
        effects.forEach((eff, index) => {
          let descClean = eff.desc.trim();
          lines.push(`损伤效果${index + 1}:DE${eff.deNum} ${descClean}`);
        });
      }

      summaryTextarea.value = lines.join('\n');
      showToast('已生成最终总结');
    }

    // 绑定总结与复制事件
    document.getElementById('summary_btn').addEventListener('click', generateSummary);
    document.getElementById('copy_summary_btn').addEventListener('click', () => {
      const text = document.getElementById('summary_text').value;
      copyToClipboard(text, '已复制最终总结');
    });

    document.getElementById('copy_damage_btn').addEventListener('click', () => {
      const text = document.getElementById('damage_result_text').value;
      copyToClipboard(text, '已复制到剪贴板');
    });
  